using System.Windows;
using System.Windows.Controls;
namespace Rewind;
internal sealed class AudioSourceSelector : Window
{
    internal AudioSourceSelector(IReadOnlyList<AudioSourceSetting> current,Func<IReadOnlyList<AudioSourceSetting>,Task> save,bool discover){Title="FLICK · Audio lanes";Width=620;Height=500;WindowStartupLocation=WindowStartupLocation.CenterOwner;Background=ThemePalette.Surface;Foreground=ThemePalette.Foreground;FontFamily=Typography.Inter;Resources.MergedDictionaries.Add(new ResourceDictionary{Source=new Uri("/FLICK;component/Theme.xaml",UriKind.Relative)});
        var root=new DockPanel{Margin=new Thickness(24)};Content=root;var message=new TextBlock{Text="Select up to six additional device endpoints. Route game and Discord to different outputs to isolate them; apps on one output remain mixed. Microphone and default desktop toggles remain separate.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,20)};DockPanel.SetDock(message,Dock.Top);root.Children.Add(message);var apply=new Button{Content="Apply audio lanes",HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,14,0,0)};DockPanel.SetDock(apply,Dock.Bottom);root.Children.Add(apply);var rows=new StackPanel();root.Children.Add(new ScrollViewer{Content=rows,VerticalScrollBarVisibility=ScrollBarVisibility.Hidden});var selected=new Dictionary<string,AudioSourceSetting>(current.ToDictionary(a=>a.Id));
        Loaded+=async(_,_)=>{try{var devices=discover?await Task.Run(AudioReplay.Endpoints):Array.Empty<AudioReplay.Endpoint>();foreach(var device in devices){var row=new DockPanel{Margin=new Thickness(0,10,0,10)};var toggle=new CheckBox{IsChecked=selected.ContainsKey(device.Id)};DockPanel.SetDock(toggle,Dock.Right);row.Children.Add(toggle);row.Children.Add(new TextBlock{Text=(device.IsInput?"Input · ":"Output · ")+device.Title,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,12,0)});toggle.Click+=(_,_)=>{if(toggle.IsChecked==true){if(selected.Count>=6){toggle.IsChecked=false;message.Text="Choose at most six additional endpoints.";return;}selected[device.Id]=new(device.Id,device.Title,device.IsInput);}else selected.Remove(device.Id);};rows.Children.Add(row);}if(devices.Length==0)rows.Children.Add(new TextBlock{Text="No active endpoints available."});}catch(Exception e){message.Text=e.Message;}};
        apply.Click+=async(_,_)=>{apply.IsEnabled=false;try{await save(selected.Values.ToArray());Close();}catch(Exception e){message.Text=e.Message;apply.IsEnabled=true;}};
    }
}
